//! Файл: settings/catalog/coinex.rs
//! Что делает: настройки, нужные только бирже CoinEx (решение 170), — имя сети BSC в справочнике адресов контрактов,
//! единицы ставки комиссии ключа и предел страницы истории выводов. Значений нет.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «Площадки и соединения»).

use super::{V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решения 170. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static COINEX: &[SettingDef] = &[
    d("Площадки", "venue.bsc_contract_chain", K::Text, L::None, "название", V, "Решение 170, только CoinEx: как сеть BSC названа в chain_info.chain_name справочника GET /v2/assets/info — оттуда берётся адрес контракта (identity); в справочнике ввода/вывода адреса нет, а имена цепей в двух справочниках по примерам документации разные («Ethereum (ERC20)» против chain). Задаётся по живому ответу /v2/assets/info?ccy=CAKE. Не задана — справочник монет CoinEx не строится (без адреса контракта монета не сопоставляется с DEX)"),
    d("Площадки", "venue.fee_rate_percent", K::Bool, L::None, "да/нет", V, "Решение 170, только CoinEx: в каких единицах GET /v2/account/trade-fee-rate отдаёт taker_rate / maker_rate — в документации не сказано (в примере \"0.03\", а ставка пары по умолчанию — \"0.002\"). Да — проценты (делится на 100), нет — доля. Решает Тигран по живому ответу («Проверить подключение» показывает ставку как пришла). Не задана — ставок комиссии и котировок CoinEx нет"),
    d("Площадки", "venue.history_page_limit", K::Integer, L::Positive, "штук", V, "Решение 170, только CoinEx: сколько последних выводов монеты читать (limit GET /v2/assets/withdraw; по умолчанию 10, максимум не указан), чтобы найти свой вывод по remark, если итог отправки неизвестен. Не задана — вывод с CoinEx не отправляется (искать его потом нечем, урок 7)"),
];
